package com.experiment.social;
import org.junit.jupiter.api.Test; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*; import java.time.Instant; import java.util.List;
class SocialServiceTest { @Test void rejectsPastSchedule(){var repo=mock(SocialPostRepository.class);var service=new SocialService(repo);assertThatThrownBy(()->service.schedule("LinkedIn","A post",Instant.now().minusSeconds(10))).hasMessageContaining("future");verifyNoInteractions(repo);} @Test void publishesDuePosts(){var repo=mock(SocialPostRepository.class);var post=new SocialPost("LinkedIn","Hello",Instant.now().minusSeconds(2));when(repo.findByStatusAndScheduledAtLessThanEqual(eq("SCHEDULED"),any())).thenReturn(List.of(post));new SocialService(repo).publishDue();assertThat(post.getStatus()).isEqualTo("PUBLISHED");assertThat(post.getPublishedAt()).isNotNull();} }
